/* WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ */
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import type { ForumContentKind, ForumGenerationConfig, ForumPost, ForumUser } from '../../../types/forum'
import { defaultForumGenerationConfig, estimateForumBatchSize, normalizeForumGenerationConfig } from '../../../services/forumGeneration'

const props = defineProps<{ visible: boolean; characters: ForumUser[]; posts?: ForumPost[]; busy?: boolean; progress?: number; error?: string; profileAccountId?: string }>()
const emit = defineEmits<{ (e: 'close'): void; (e: 'confirm', config: ForumGenerationConfig): void }>()
const form = reactive(defaultForumGenerationConfig())
const confirmLarge = ref(false)
const presets = [3, 5, 10]
const kinds: Array<{ id: ForumContentKind; label: string }> = [
  { id: 'thought', label: '碎碎念' }, { id: 'life', label: '日常生活' }, { id: 'image-share', label: '图片分享' }, { id: 'question', label: '提问' },
  { id: 'help', label: '求助' }, { id: 'complaint', label: '吐槽' }, { id: 'experience', label: '经历' }, { id: 'discussion', label: '讨论/长文' },
  { id: 'link', label: '链接' }, { id: 'poll', label: '投票' }, { id: 'anonymous', label: '匿名' }, { id: 'circle-topic', label: '圈子话题' }
]
const generatedPosts = computed(() => (props.posts || []).filter(post => post.source !== 'user'))
const valid = computed(() => form.postCount >= 1 && form.requiredCharacterAccountIds.length <= form.postCount && (form.postTypeMode === 'natural' || form.allowedContentKinds.length > 0) && (form.refreshMode !== 'replace' || form.replaceScope !== 'selected' || form.replacePostIds.length > 0))
const batchSize = computed(() => estimateForumBatchSize(normalizeForumGenerationConfig(form), 5000))
const batchCount = computed(() => Math.ceil(form.postCount / batchSize.value))
const characterHint = computed(() => !form.requiredCharacterAccountIds.length ? '可不选；系统按重复策略安排 NPC' : `保证包含 ${form.requiredCharacterAccountIds.length} 位角色`)

watch(() => props.visible, visible => {
  if (!visible) return
  Object.assign(form, defaultForumGenerationConfig(), props.profileAccountId ? { profileAccountId: props.profileAccountId, requiredCharacterAccountIds: [props.profileAccountId], discoverCircles: false } : {})
  confirmLarge.value = false
})
const toggleKind = (kind: ForumContentKind) => { const index = form.allowedContentKinds.indexOf(kind); if (index >= 0) form.allowedContentKinds.splice(index, 1); else form.allowedContentKinds.push(kind) }
const toggleCharacter = (accountId: string) => { const index = form.requiredCharacterAccountIds.indexOf(accountId); if (index >= 0) form.requiredCharacterAccountIds.splice(index, 1); else if (form.requiredCharacterAccountIds.length < form.postCount) form.requiredCharacterAccountIds.push(accountId) }
const toggleReplacePost = (postId: string) => { const index = form.replacePostIds.indexOf(postId); if (index >= 0) form.replacePostIds.splice(index, 1); else form.replacePostIds.push(postId) }
const submit = () => { if (!valid.value || props.busy) return; if (form.postCount > 20 && !confirmLarge.value) { confirmLarge.value = true; return }; emit('confirm', normalizeForumGenerationConfig(form)) }
</script>

<template>
  <div v-if="visible" class="refresh-overlay" @click.self="emit('close')">
    <section class="refresh-sheet" role="dialog" aria-modal="true" aria-labelledby="forum-refresh-title">
      <header><div><h2 id="forum-refresh-title">{{profileAccountId?'刷新 NPC 主页':'刷新论坛'}}</h2><p>{{busy?'生成任务在论坛后台继续运行':'首页刷新与单帖增量互动相互独立'}}</p></div><button type="button" aria-label="关闭" @click="emit('close')">×</button></header>
      <div v-if="confirmLarge" class="large-confirm"><b>确认生成 {{form.postCount}} 篇？</b><p>预计拆为约 {{batchCount}} 个技术批次。批次大小会按帖子类型、评论量、NPC 模式与 API 输出能力动态调整，时间和 API 消耗都会增加。</p><div><button @click="confirmLarge=false">返回修改</button><button class="primary" @click="submit">确认并开始</button></div></div>
      <div v-else class="form-body">
        <section class="field-block"><div class="field-title"><b>刷新方式</b><small>默认保留现有内容</small></div><div class="choice-row"><button :class="{active:form.refreshMode==='incremental'}" @click="form.refreshMode='incremental'">增量刷新</button><button :class="{active:form.refreshMode==='replace'}" @click="form.refreshMode='replace'">覆盖刷新</button></div>
          <div v-if="form.refreshMode==='replace'" class="nested"><div class="choice-row three"><button :class="{active:form.replaceScope==='latest-batch'}" @click="form.replaceScope='latest-batch'">最近批次</button><button :class="{active:form.replaceScope==='selected'}" @click="form.replaceScope='selected'">选择帖子</button><button :class="{active:form.replaceScope==='all-generated'}" @click="form.replaceScope='all-generated'">全部生成帖</button></div><p>用户帖子、用户评论、手动保留帖及含用户参与的帖子默认受保护。</p><div v-if="form.replaceScope==='selected'" class="replace-list"><label v-for="post in generatedPosts" :key="post.id"><input type="checkbox" :checked="form.replacePostIds.includes(post.id)" :disabled="post.isKept" @change="toggleReplacePost(post.id)"><span>{{post.isKept?'已保留 · ':''}}{{post.content.slice(0,46)||'无正文'}}</span></label></div></div>
        </section>
        <section class="field-block"><div class="field-title"><b>生成帖子</b><small>不设业务硬上限；超过 20 二次确认</small></div><div class="count-row"><button v-for="count in presets" :key="count" :class="{active:form.postCount===count}" @click="form.postCount=count;form.requiredCharacterAccountIds.splice(count)">{{count}} 篇</button><label :class="{active:!presets.includes(form.postCount)}"><span>自定义</span><input v-model.number="form.postCount" type="number" min="1" @change="form.requiredCharacterAccountIds.splice(form.postCount)"></label></div></section>
        <section class="field-block"><div class="field-title"><b>帖子类型</b><small>基于现有 contentKind / ForumPostType</small></div><div class="choice-row"><button :class="{active:form.postTypeMode==='natural'}" @click="form.postTypeMode='natural'">自然混合</button><button :class="{active:form.postTypeMode==='custom'}" @click="form.postTypeMode='custom'">自定义选择</button></div><template v-if="form.postTypeMode==='custom'"><div class="chip-grid"><button v-for="kind in kinds" :key="kind.id" :class="{active:form.allowedContentKinds.includes(kind.id)}" @click="toggleKind(kind.id)">{{kind.label}}</button></div><label class="switch-line"><span>每种已选类型至少一篇</span><input v-model="form.ensureEverySelectedKind" type="checkbox"></label><div v-if="form.allowedContentKinds.includes('anonymous')" class="compact-choice"><span>匿名帖无圈子时</span><select v-model="form.anonymousUnavailable"><option value="skip">不生成此类型</option><option value="existing-circle">必须使用现有圈子</option><option value="create-circle">允许本轮创建圈子</option></select></div><div v-if="form.allowedContentKinds.includes('circle-topic')" class="compact-choice"><span>圈子话题无圈子时</span><select v-model="form.circleTopicUnavailable"><option value="skip">不生成此类型</option><option value="existing-circle">必须使用现有圈子</option><option value="create-circle">允许本轮创建圈子</option></select></div><div v-if="form.allowedContentKinds.includes('image-share')" class="compact-choice"><span>图片来源不可用时</span><select v-model="form.imageUnavailable"><option value="skip">不生成此类型</option><option value="ai">要求 AI 生图</option><option value="text">允许无图文字动态</option></select></div></template></section>
        <section class="field-block"><div class="field-title"><b>初始评论</b><small>只作用于本轮新帖</small></div><label class="switch-line"><span>为新帖生成初始评论</span><input v-model="form.includeInitialComments" type="checkbox"></label><template v-if="form.includeInitialComments"><div class="choice-row three"><button :class="{active:form.commentMode==='natural'}" @click="form.commentMode='natural'">自然分布</button><button :class="{active:form.commentMode==='per-post'}" @click="form.commentMode='per-post'">每帖固定</button><button :class="{active:form.commentMode==='total'}" @click="form.commentMode='total'">总量指定</button></div><label v-if="form.commentMode==='per-post'" class="number-line"><span>每帖评论</span><input v-model.number="form.commentsPerPost" type="number" min="0"><i>条</i></label><label v-if="form.commentMode==='total'" class="number-line"><span>本轮总评论</span><input v-model.number="form.totalComments" type="number" min="0"><i>条</i></label></template></section>
        <section class="field-block"><div class="field-title"><b>NPC</b><small>两种模式都保持身份连续</small></div><div class="choice-row"><button :class="{active:form.npcGenerationMode==='lightweight'}" @click="form.npcGenerationMode='lightweight'">快速轻量</button><button :class="{active:form.npcGenerationMode==='full'}" @click="form.npcGenerationMode='full'">完整 NPC</button></div><div class="choice-row three top-gap"><button :class="{active:form.strangerRepeatMode==='avoid'}" @click="form.strangerRepeatMode='avoid'">尽量不重复</button><button :class="{active:form.strangerRepeatMode==='natural'}" @click="form.strangerRepeatMode='natural'">自然混合</button><button :class="{active:form.strangerRepeatMode==='allow'}" @click="form.strangerRepeatMode='allow'">允许重复</button></div></section>
        <section v-if="!profileAccountId" class="field-block"><div class="field-title"><b>新圈子</b><small>创建后必须有真实帖子绑定</small></div><div class="choice-row"><button :class="{active:form.discoverCircles}" @click="form.discoverCircles=true">自动发现</button><button :class="{active:!form.discoverCircles}" @click="form.discoverCircles=false">本轮不创建</button></div></section>
        <section v-if="!profileAccountId" class="field-block"><div class="field-title"><b>参与角色</b><small>{{characterHint}}</small></div><div v-if="characters.length" class="character-list"><button v-for="user in characters" :key="user.id" :class="{selected:form.requiredCharacterAccountIds.includes(user.id)}" @click="toggleCharacter(user.id)"><i>✓</i><span>{{user.name}}</span></button></div><p v-else class="nested">聊天 App 中暂无可参与角色，也可完全由论坛 NPC 生成。</p></section>
        <p v-if="!valid" class="validation">请检查帖子数量、类型、覆盖目标及参与角色数量。</p><p v-else-if="error" class="validation">{{error}}</p>
      </div>
      <div v-if="busy" class="progress"><span :style="{width:`${progress||0}%`}"></span><small>正在生成 {{progress||0}}%</small></div>
      <footer v-if="!confirmLarge"><button class="cancel" @click="emit('close')">{{busy?'收起':'取消'}}</button><button class="confirm" :disabled="busy||!valid" @click="submit">{{busy?'后台生成中…':`生成 ${form.postCount} 篇`}}</button></footer>
    </section>
  </div>
</template>

<style scoped>
.refresh-overlay{position:absolute;inset:0;z-index:520;display:flex;align-items:flex-end;background:rgba(0,0,0,.34)}.refresh-sheet{box-sizing:border-box;width:100%;max-height:min(90%,720px);display:flex;flex-direction:column;border-radius:16px 16px 0 0;background:var(--sys-bg-secondary,#fff);padding:5px 14px calc(9px + env(safe-area-inset-bottom,0px));box-shadow:0 -8px 28px rgba(0,0,0,.08)}header{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:52px;border-bottom:1px solid var(--border-color,rgba(0,0,0,.06))}header>div{min-width:0;flex:1}h2{margin:0;font-size:14px;font-weight:650}header p{margin:2px 0 0;color:var(--text-tertiary,#999);font-size:10.5px}header>button{width:28px;height:28px;border:0;border-radius:50%;background:transparent;color:var(--text-secondary,#777);font-size:20px}.form-body{min-height:0;overflow:auto}.field-block{padding:12px 1px;border-bottom:1px solid var(--border-color,rgba(0,0,0,.055))}.field-title{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:8px}.field-title b{font-size:12.5px}.field-title small{color:var(--text-tertiary,#999);font-size:9.8px;text-align:right}.choice-row,.count-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.choice-row.three{grid-template-columns:repeat(3,minmax(0,1fr))}.top-gap{margin-top:7px}.choice-row button,.count-row button,.count-row label,.chip-grid button{box-sizing:border-box;min-height:34px;border:1px solid transparent;border-radius:9px;background:var(--sys-bg-primary,#f3f4f6);color:var(--text-secondary,#666);font:inherit;font-size:11px}.choice-row button.active,.count-row button.active,.count-row label.active,.chip-grid button.active{border-color:color-mix(in srgb,var(--accent-color,#2b7de9) 42%,transparent);background:color-mix(in srgb,var(--accent-color,#2b7de9) 9%,transparent);color:var(--accent-color,#2b7de9);font-weight:600}.count-row{grid-template-columns:repeat(4,minmax(0,1fr))}.count-row label{position:relative;display:flex;align-items:center;justify-content:center}.count-row input{position:absolute;inset:0;width:100%;border:0;background:transparent;color:transparent;text-align:center;outline:0;appearance:textfield}.count-row label:focus-within span{display:none}.count-row label:focus-within input{color:var(--text-primary,#222)}.chip-grid{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.chip-grid button{min-height:29px;padding:0 9px}.switch-line,.number-line{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;color:var(--text-secondary,#666);font-size:11px}.switch-line input{width:16px;height:16px;accent-color:var(--accent-color,#576b95)}.number-line input{box-sizing:border-box;width:78px;height:31px;border:1px solid var(--border-color,#ddd);border-radius:8px;background:var(--sys-bg-primary,#f5f5f7);color:var(--text-primary,#222);padding:0 8px;text-align:right}.number-line i{font-style:normal}.nested{margin-top:8px;padding:8px;border-radius:9px;background:var(--sys-bg-primary,#f6f6f7);color:var(--text-tertiary,#888);font-size:10px;line-height:1.5}.nested p{margin:7px 0 0}.replace-list{max-height:150px;overflow:auto;margin-top:7px}.replace-list label{display:flex;align-items:center;gap:7px;padding:6px 2px;border-top:1px solid var(--border-color,rgba(0,0,0,.05))}.replace-list input{accent-color:var(--accent-color,#576b95)}.replace-list span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.character-list{display:flex;flex-wrap:wrap;gap:6px}.character-list button{display:flex;height:31px;align-items:center;gap:6px;padding:0 9px;border:1px solid transparent;border-radius:9px;background:var(--sys-bg-primary,#f3f4f6);color:var(--text-secondary,#666);font:inherit;font-size:11px}.character-list i{display:flex;width:14px;height:14px;align-items:center;justify-content:center;border:1px solid #c5c7ca;border-radius:4px;color:transparent;font-size:9px;font-style:normal}.character-list button.selected i{border-color:var(--accent-color,#576b95);background:var(--accent-color,#576b95);color:#fff}.validation{margin:9px 1px 2px;color:#c24a4a;font-size:10px}.progress{position:relative;flex:0 0 22px;overflow:hidden;border-radius:7px;background:var(--sys-bg-primary,#f2f3f5)}.progress>span{position:absolute;inset:0 auto 0 0;background:color-mix(in srgb,var(--accent-color,#2b7de9) 25%,transparent)}.progress small{position:relative;display:block;text-align:center;color:var(--text-secondary,#666);font-size:9.5px;line-height:22px}footer{display:flex;gap:8px;padding-top:9px}footer button,.large-confirm button{height:36px;border:0;border-radius:10px;font:inherit;font-size:12px;font-weight:600}.cancel{flex:0 0 30%;background:var(--sys-bg-primary,#f1f2f4);color:var(--text-secondary,#666)}.confirm,.large-confirm .primary{flex:1;background:var(--accent-color,#2b7de9);color:#fff}button:disabled{opacity:.38}.large-confirm{padding:28px 8px 18px}.large-confirm b{font-size:16px}.large-confirm p{color:var(--text-secondary,#666);font-size:12px;line-height:1.65}.large-confirm>div{display:flex;gap:8px}.large-confirm button{flex:1;background:var(--sys-bg-primary,#f1f2f4);color:var(--text-secondary,#666)}@media(max-width:360px){.refresh-sheet{padding-left:10px;padding-right:10px}.choice-row.three{grid-template-columns:1fr}.count-row{grid-template-columns:repeat(2,1fr)}}
.compact-choice{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:7px;color:var(--text-secondary,#666);font-size:10.5px}.compact-choice select{height:29px;border:1px solid var(--border-color,#ddd);border-radius:8px;background:var(--sys-bg-primary,#f5f5f7);color:inherit;padding:0 6px;font:inherit;font-size:10px}
</style>
